mapper.select:
SELECT t.* FROM edu_paper_template t


        AND t.template_name LIKE CONCAT('%', #{name}, '%')


        AND t.template_style = #{style}


        AND t.template_status = #{status}



            AND (t.template_owner_user_id IS NULL OR t.template_owner_user_id = #{scope.ownerPredicate})



ORDER BY t.template_id DESC
